from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    for r in range(h):
        if len(set(grid[r])) == 1:
            base = Counter(v for row in grid[:r] for v in row).most_common(1)[0][0]
            panel = grid[r + 1:]
            return [[3 if v == base else base for v in row] for row in panel]
    for c in range(w):
        if len({row[c] for row in grid}) == 1:
            base = Counter(grid[r][j] for r in range(h) for j in range(c)).most_common(1)[0][0]
            return [[3 if grid[r][j] == base else base for j in range(c + 1, w)] for r in range(h)]
    raise ValueError('separator not found')

